/** Discover all candidate files for a runtime (unsorted). */
export async function discover(runtime: SessionRuntime): Promise<Candidate[]> {
  const root =
    runtime === 'claude' ? claudeProjectsRoot() : codexSessionsRoot();
  const files = await walk(root, (name) =>
    runtime === 'claude'
      ? name.endsWith('.jsonl')
      : name.startsWith('rollout-') && name.endsWith('.jsonl'),
  );

  const candidates: Candidate[] = [];
  for (const filePath of files) {
    try {
      const st = await stat(filePath);
      candidates.push({
        runtime,
        filePath,
        mtimeMs: st.mtimeMs,
        sizeBytes: st.size,
      });
    } catch {
      // File vanished between walk and stat — skip.
    }
  }
  return candidates;
}

