/**
 * First non-sidechain user prompt within the file's first
 * `PREVIEW_HEAD_BYTES` — used ONLY to build a preview when no capture record
 * already carries one. Exported for `index.ts`'s listing builder.
 */
export async function readFirstUserPromptBounded(filePath: string): Promise<string | undefined> {
  try {
    const text = await Bun.file(filePath).slice(0, PREVIEW_HEAD_BYTES).text();
    for (const rawLine of text.split('\n')) {
      const obj = parseJsonLine(rawLine);
      if (!obj) continue;
      if (obj.type === 'user' && obj.isSidechain !== true) {
        const message = obj.message as Record<string, unknown> | undefined;
        const text2 = message ? contentToText(message.content) : '';
        if (text2) return text2;
      }
    }
  } catch {
    // Unreadable/vanished file — no preview from the transcript.
  }
  return undefined;
}

